INSERT INTO bare_acts (id, title, short_title, is_active)
INSERT INTO bare_act_sections (section_number, section_title, section_text, chapter_number, chapter_title, sequence_order, act_id)
VALUES 
('GWA-1', 'Title, extent and commencement', 'This Act may be called the Guardians and Wards Act, 1890. It extends to the whole of India.', 'CH1_PRELIMINARY', 'Preliminary', 1, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-4', 'Definitions', 'In this Act, unless there is something repugnant in the subject or context:\n(1) ''minor'' means a person who has not attained the age of eighteen years;\n(2) ''guardian'' means a person having the care of the person of a minor or of his property or of both;\n(3) ''ward'' means a minor for whose person or property or both there is a guardian;\n(5) ''court'' means the district court having jurisdiction.', 'CH1_PRELIMINARY', 'Preliminary', 2, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-7', 'Power of the Court to make order as to guardianship', 'Where the Court is satisfied that it is for the welfare of a minor that an order should be made appointing a guardian of his person or property or both, or declaring a person to be such a guardian, the Court may make an order accordingly.', 'CH2_APPOINTMENT', 'Appointment and Declaration of Guardians', 3, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-9', 'Court having jurisdiction to entertain application', 'If the application is with respect to the guardianship of the person of the minor, it shall be made to the district court having jurisdiction in the place where the minor ordinarily resides.\n\nNote: ''Ordinarily resides'' is a key legal term. It refers to a permanent or settled place of residence of the minor, not a temporary visit.', 'CH2_APPOINTMENT', 'Appointment and Declaration of Guardians', 4, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-12', 'Power to make interlocutory order for production of minor', 'The Court may direct that the person having the custody of the minor shall produce him or cause him to be produced at such place and time as the Court appoints. The Court may also make such order for the interim protection of the person or property of the minor as it thinks fit.\n\nNote: This is often used for interim custody and visitation during pendency of the main case.', 'CH2_APPOINTMENT', 'Appointment and Declaration of Guardians', 5, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-17', 'Matters to be considered by the Court in appointing guardian', 'In appointing or declaring the guardian of a minor, the Court shall, subject to the provisions of this section, be guided by what, consistently with the law to which the minor is subject, appears in the circumstances to be for the welfare of the minor.\n\nIn considering what will be for the welfare of the minor, the Court shall have regard to the age, sex and religion of the minor, the character and capacity of the proposed guardian and his nearness of kin to the minor, the wishes, if any, of a deceased parent, and any existing or previous relations of the proposed guardian with the minor or his property. If the minor is old enough to form an intelligent preference, the Court may consider that preference.', 'CH2_APPOINTMENT', 'Appointment and Declaration of Guardians', 6, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-19', 'Guardian not to be appointed by the Court in certain cases', 'Nothing in this Chapter shall authorize the Court to appoint or declare a guardian of the person of a minor:\n(a) who is a married female and whose husband is not, in the opinion of the Court, unfit to be guardian of her person; or\n(b) of a minor whose father is living and is not, in the opinion of the Court, unfit to be guardian of the person of the minor.', 'CH2_APPOINTMENT', 'Appointment and Declaration of Guardians', 7, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-20', 'Fiduciary relation of guardian to ward', 'A guardian stands in a fiduciary relation to his ward, and, save as provided by the will or other instrument, if any, by which he was appointed, or by this Act, he must not make any profit out of his office.', 'CH3_DUTIES', 'Duties, Rights and Liabilities of Guardians', 8, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-24', 'Duties of guardian of the person', 'A guardian of the person of a ward is charged with the custody of the ward and must look to his support, health and education, and such other matters as the law to which the ward is subject requires.', 'CH3_DUTIES', 'Duties, Rights and Liabilities of Guardians', 9, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-25', 'Title of guardian to custody of ward', 'If a ward leaves or is removed from the custody of a guardian of his person, the Court, if it is of opinion that it will be for the welfare of the ward that he should be returned to the custody of his guardian, may make an order for his return, and for the purpose of enforcing the order may cause the ward to be arrested and to be delivered into the custody of the guardian.', 'CH3_DUTIES', 'Duties, Rights and Liabilities of Guardians', 10, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-27', 'Duties of guardian of property', 'A guardian of the property of a ward is bound to deal therewith as carefully as a man of ordinary prudence would deal with it if it were his own, and, subject to the provisions of this Chapter, he may do all acts which are reasonable and proper for the realization, protection or benefit of the property.', 'CH3_DUTIES', 'Duties, Rights and Liabilities of Guardians', 11, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-29', 'Limitation of powers of guardian of property appointed by Court', 'Where a person other than a collector, or than a guardian appointed by will or other instrument, has been appointed or declared by the Court to be guardian of the property of a ward, he shall not, without the previous permission of the Court:\n(a) mortgage or charge, or transfer by sale, gift, exchange or otherwise, any part of the immovable property of his ward; or\n(b) lease any part of that property for a term exceeding five years or for any term extending more than one year beyond the date on which the ward will cease to be a minor.', 'CH3_DUTIES', 'Duties, Rights and Liabilities of Guardians', 12, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-39', 'Removal of guardian', 'The Court may, on the application of any person interested or of its own motion, remove a guardian appointed or declared by the Court, or a guardian appointed by will or other instrument, for any of the following causes, namely:\n(a) for abuse of his trust;\n(b) for continued failure to perform the duties of his office;\n(c) for incapacity to perform the duties of his office;\n(d) for ill-treatment, or neglect to take proper care, of his ward;\n(e) for contumacious disregard of any provision of this Act or of any order of the Court;\n(f) for conviction of an offence implying, in the opinion of the Court, a defect of character which unfits him to be the guardian of his ward.', 'CH3_DUTIES', 'Duties, Rights and Liabilities of Guardians', 13, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d'),
('GWA-41', 'Cessation of authority of guardian', 'The powers of a guardian of the person or property cease:\n(a) by his death, removal or discharge;\n(b) by the Court of Wards assuming superintendence of the person or property of the ward;\n(c) by the ward ceasing to be a minor;\n(d) in the case of a female ward, by her marriage to a person whose husband is not unfit to be guardian of her person.', 'CH3_DUTIES', 'Duties, Rights and Liabilities of Guardians', 14, '5c33a921-1e11-477d-844a-8e1e4a1f6d4d');
